	app := &server{
		documents:    documents,
		monitors:     monitors,
		mcpStore:     mcpStore,
		llm:          llm,
		history:      history,
		model:        model,
		models:       options,
		allowed:      allowed,
		agentOptions: agentOptions,
		sessions:     make(map[string]*sessionEntry),
