package web

import (
	"crypto/rand"
	"embed"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"mime"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"

	"codex-chat-cli/internal/agent"
	"codex-chat-cli/internal/docindex"
	"codex-chat-cli/internal/mcpclient"
	"codex-chat-cli/internal/memory"
	"codex-chat-cli/internal/models"
	"codex-chat-cli/internal/profile"
	"codex-chat-cli/internal/rag"
	"codex-chat-cli/internal/scheduler"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

const (
	maxRequestBytes = 1 << 20
	maxOptionLength = 4000
	maxContextKeep  = 1000
	sessionCookie   = "codex_chat_session"
	sessionTTL      = 12 * time.Hour
	cookieTTL       = 365 * 24 * time.Hour
	maxSessions     = 256
)

//go:embed static/index.html static/app.css static/app.js static/memory.js static/task-state.js static/invariants.js static/profiles.js static/mcp.js static/monitors.js static/documents.js static/rag.js static/rag23.js static/rag24.js static/rag25.js static/markdown.js static/favicon.svg
var staticFiles embed.FS

type sessionEntry struct {
	agent    *agent.Agent
	lastUsed time.Time
}

type server struct {
	documents    *docindex.Service
	monitors     *scheduler.Service
	mcpStore     *mcpclient.Store
	llm          agent.LLM
	history      agent.History
	model        string
	models       []modelOption
	allowed      map[string]bool
	agentOptions []agent.Option

	mu       sync.Mutex
	sessions map[string]*sessionEntry
}

type chatRequest struct {
	RAGOptions          *agent.RetrievalOptions `json:"ragOptions,omitempty"`
	RAG                 bool                    `json:"rag,omitempty"`
	TaskID              string                  `json:"taskId,omitempty"`
	TaskVersion         *int                    `json:"taskVersion,omitempty"`
	ProfileID           string                  `json:"profileId,omitempty"`
	Message             string                  `json:"message"`
	Model               string                  `json:"model,omitempty"`
	ResponseFormat      string                  `json:"responseFormat,omitempty"`
	LengthLimit         string                  `json:"lengthLimit,omitempty"`
	CompletionCondition string                  `json:"completionCondition,omitempty"`
	Temperature         *float64                `json:"temperature,omitempty"`
	ContextStrategy     string                  `json:"contextStrategy,omitempty"`
	ContextKeepLast     *int                    `json:"contextKeepLast,omitempty"`
}

type apiResponse struct {
	MCP      *mcpView                `json:"mcp,omitempty"`
	Profiles *agent.ProfileView      `json:"profiles,omitempty"`
	Memory   *agent.MemoryView       `json:"memory,omitempty"`
	Answer   string                  `json:"answer,omitempty"`
	Error    string                  `json:"error,omitempty"`
	Warning  string                  `json:"warning,omitempty"`
	Model    string                  `json:"model,omitempty"`
	Models   []modelOption           `json:"models,omitempty"`
	Metrics  *responseMetrics        `json:"metrics,omitempty"`
	Messages []agent.Message         `json:"messages,omitempty"`
	Context  *agent.StrategySnapshot `json:"context,omitempty"`
}

type branchRequest struct {
	BranchID string `json:"branchId"`
}

type modelOption struct {
	ID    string `json:"id"`
	Label string `json:"label"`
}

type responseMetrics struct {
	DurationMS        int64    `json:"durationMs"`
	InputTokens       int      `json:"inputTokens"`
	CachedInputTokens int      `json:"cachedInputTokens"`
	CacheWriteTokens  int      `json:"cacheWriteTokens"`
	OutputTokens      int      `json:"outputTokens"`
	ReasoningTokens   int      `json:"reasoningTokens"`
	TotalTokens       int      `json:"totalTokens"`
	CostUSD           *float64 `json:"costUsd"`
	agent.TokenMetrics
}

// NewHandler returns the complete local web application handler.
func NewHandler(llm agent.LLM, model string, history agent.History, agentOptions ...agent.Option) http.Handler {
	return NewHandlerWithMCP(llm, model, history, nil, agentOptions...)
}

// NewHandlerWithMCP adds project-wide MCP connection settings to the web app.
func NewHandlerWithMCP(llm agent.LLM, model string, history agent.History, mcpStore *mcpclient.Store, agentOptions ...agent.Option) http.Handler {
	return NewHandlerWithScheduler(llm, model, history, mcpStore, nil, agentOptions...)
}

func NewHandlerWithScheduler(llm agent.LLM, model string, history agent.History, mcpStore *mcpclient.Store, monitors *scheduler.Service, agentOptions ...agent.Option) http.Handler {
	return NewHandlerWithDocuments(llm, model, history, mcpStore, monitors, nil, agentOptions...)
}

func NewHandlerWithDocuments(llm agent.LLM, model string, history agent.History, mcpStore *mcpclient.Store, monitors *scheduler.Service, documents *docindex.Service, agentOptions ...agent.Option) http.Handler {
	if documents != nil {
		agentOptions = append(agentOptions, agent.WithRetriever(rag.Retriever{Documents: documents, LLM: llm, Model: model}))
	}
	var localMCP *mcp.Server
	if monitors != nil {
		localMCP = monitors.MCP(mcpStore)
	}
	var remote agent.ToolProvider
	if mcpStore != nil {
		remote = mcpclient.NewProvider(mcpStore)
	}
	if monitors != nil {
		agentOptions = append(agentOptions, agent.WithTools(&scheduler.Provider{Service: monitors, Server: localMCP, Remote: remote}))
	} else if remote != nil {
		agentOptions = append(agentOptions, agent.WithTools(remote))
	}
	model = strings.TrimSpace(model)
	definitions := models.Available(model)
	options := make([]modelOption, 0, len(definitions))
	allowed := make(map[string]bool, len(definitions))
	for _, definition := range definitions {
		options = append(options, modelOption{ID: definition.ID, Label: definition.Label})
		allowed[definition.ID] = true
	}
	app := &server{
		documents:    documents,
		monitors:     monitors,
		mcpStore:     mcpStore,
		llm:          llm,
		history:      history,
		model:        model,
		models:       options,
		allowed:      allowed,
		agentOptions: agentOptions,
		sessions:     make(map[string]*sessionEntry),
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/rag.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "rag.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/rag23.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "rag23.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/rag24.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "rag24.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/rag25.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "rag25.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/api/rag/dialogues", app.handleRAGDialogues)
	mux.HandleFunc("/api/rag/grounding", app.handleRAGGrounding)
	mux.HandleFunc("/api/rag/experiment", app.handleRAGExperiment)
	mux.HandleFunc("/api/rag/run", app.handleRAGRun)
	mux.HandleFunc("/api/rag/report", app.handleRAGReport)
	mux.HandleFunc("/api/rag/compare", app.handleRAGCompare)
	mux.HandleFunc("/documents.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "documents.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/api/documents", app.handleDocuments)
	mux.HandleFunc("/api/documents/chunks", app.handleDocumentChunks)
	mux.HandleFunc("/api/documents/search", app.handleDocumentSearch)
	mux.HandleFunc("/monitors.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "monitors.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/api/monitors", app.handleMonitors)
	for _, path := range []string{"/api/monitors/create", "/api/monitors/pause", "/api/monitors/settings", "/api/monitors/update", "/api/monitors/preview", "/api/monitors/run", "/api/monitors/delete"} {
		mux.HandleFunc(path, app.handleMonitorMutation)
	}
	if localMCP != nil {
		handler := mcp.NewStreamableHTTPHandler(func(*http.Request) *mcp.Server { return localMCP }, &mcp.StreamableHTTPOptions{Stateless: true, JSONResponse: true})
		mux.HandleFunc("/mcp/scheduler", func(w http.ResponseWriter, r *http.Request) {
			if r.Method != http.MethodPost && r.Method != http.MethodGet && r.Method != http.MethodDelete {
				w.WriteHeader(405)
				return
			}
			if !allowAPIRequest(w, r, r.Method) {
				return
			}
			r.Body = http.MaxBytesReader(w, r.Body, 64<<10)
			handler.ServeHTTP(w, r)
		})
	}
	mux.HandleFunc("/mcp.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "mcp.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/api/mcp", app.handleMCP)
	mux.HandleFunc("/api/mcp/save", app.handleMCPMutation)
	mux.HandleFunc("/api/mcp/delete", app.handleMCPMutation)
	mux.HandleFunc("/api/mcp/check", app.handleMCPMutation)
	mux.HandleFunc("/api/mcp/permissions", app.handleMCPMutation)
	mux.HandleFunc("/", app.handleIndex)
	mux.HandleFunc("/app.css", app.handleCSS)
	mux.HandleFunc("/app.js", app.handleJS)
	mux.HandleFunc("/task-state.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "task-state.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/memory.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "memory.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/markdown.js", app.handleMarkdownJS)
	mux.HandleFunc("/favicon.svg", app.handleFavicon)
	mux.HandleFunc("/api/chat", app.handleChat)
	mux.HandleFunc("/api/history", app.handleHistory)
	mux.HandleFunc("/api/reset", app.handleReset)
	mux.HandleFunc("/api/branches/create", app.handleCreateBranches)
	mux.HandleFunc("/api/branches/switch", app.handleSwitchBranch)
	mux.HandleFunc("/api/status", app.handleStatus)
	mux.HandleFunc("/healthz", app.handleHealth)
	mux.HandleFunc("/api/memory", app.handleMemory)
	mux.HandleFunc("/api/memory/review", app.handleMemoryMutation)
	mux.HandleFunc("/api/memory/from-message", app.handleMemoryMutation)
	mux.HandleFunc("/api/memory/edit", app.handleMemoryMutation)
	mux.HandleFunc("/api/memory/delete", app.handleMemoryMutation)
	mux.HandleFunc("/api/tasks/new", app.handleMemoryMutation)
	mux.HandleFunc("/api/tasks/switch", app.handleMemoryMutation)
	mux.HandleFunc("/api/tasks/state", app.handleWorkflow)
	mux.HandleFunc("/api/tasks/invariants", app.handleInvariants)
	mux.HandleFunc("/invariants.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "invariants.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/profiles.js", func(w http.ResponseWriter, r *http.Request) {
		app.serveStatic(w, r, "profiles.js", "text/javascript; charset=utf-8")
	})
	mux.HandleFunc("/api/profiles", app.handleProfiles)
	mux.HandleFunc("/api/profiles/new", app.handleProfileMutation)
	mux.HandleFunc("/api/profiles/edit", app.handleProfileMutation)
	mux.HandleFunc("/api/profiles/switch", app.handleProfileMutation)
	return securityHeaders(mux)
}

func (s *server) handleIndex(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	s.serveStatic(w, r, "index.html", "text/html; charset=utf-8")
}

