		h.ServeHTTP(w, r)
	})
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		if _, err := CurrentBranch(r.Context(), root); err != nil {
			http.Error(w, "Git unavailable", 503)
			return
		}
		w.Write([]byte("ok\n"))
	})
	return mux
}
